sys_script_vtable.script:
(function executeQuery(v_table, v_query) {
	/* global gs, x_itx_codesearch */
	/* global GlideRecord, GlideAggregate */
	/* eslint no-undef: "error" */

	const util = new x_itx_codesearch.Utilities();
	const query = util.transformRemoteTableQuery('table', v_query.getEncodedQuery());

	const tableGr = new GlideRecord('sys_db_object');
	if (query) {
		tableGr.addEncodedQuery(query);
	}

	if (/^(table\.)?sys_id=[a-z0-9]{32}$/.test(query)) {
		tableGr.setLimit(1);
	} else {
		tableGr.setLimit(100);
	}

	const dataCondition = v_query.getCondition('data');
	const term = dataCondition?.startsWith('dataCONTAINS')
		? dataCondition.substring('dataCONTAINS'.length)
		: dataCondition?.startsWith('dataLIKE')
		? dataCondition.substring('dataLIKE'.length)
		: '';

	if (!term && !tableGr.getEncodedQuery()) {
		gs.addErrorMessage('Please specify a search term (Data) or table-filter (Table)');
		return;
	}

	if (term) {
		const tableCond = tableGr.addQuery('sys_id', term);
		util.getTableFields('sys_db_object').forEach(field =>
			tableCond.addOrCondition(field.name, 'CONTAINS', term)
		);

		// search tables building the table's data structure (fields, labels and choice values)
		['sys_documentation', 'sys_dictionary', 'sys_choice_set', 'sys_choice'].forEach(table => {
			const anyGa = new GlideAggregate(table);
			const cond = anyGa.addQuery('sys_id', term);
			const fields = util.getTableFields(table);
			fields.forEach(field => {
				if (field.name != 'name') {
					// name field can be ignored -> already covered by tableGr
					cond.addOrCondition(field.name, 'CONTAINS', term);
				}
			});
			anyGa.groupBy('name');
			anyGa.query();
			while (anyGa.next()) {
				tableCond.addOrCondition('name', anyGa.getValue('name'));		
			}
		});
	}

	tableGr.orderByDesc('sys_updated_on');
	tableGr.query();

	const handler = new x_itx_codesearch.CodeSearchHandlerTable();
	while (tableGr.next()) {
		const data = handler.toJSON(tableGr);
		const dataStr = JSON.stringify(data, null, 4);
		v_table.addRow({
			sys_id: tableGr.getUniqueValue(),
			sys_class_name: tableGr.getRecordClassName(),
			sys_scope: tableGr.getValue('sys_scope'),
			table: tableGr.getUniqueValue(),
			data: dataStr,
			actions: 'c838fd22c371f690de14d8477d013160'
		});
	}
  })(v_table, v_query); /* global v_table, v_query */
